(()=>{const bank=[{"id":"ege-physics-mechanics-735","exam":"ege","domain":"physics","grade":11,"subject":"physics","topic":0,"topicName":"Механика","examTopic":"physics-ege-mechanics","level":1,"challenge":false,"title":"Первая космическая скорость","question":"Радиус однородной планеты вдвое больше земного, а средняя плотность равна земной. Во сколько раз её первая космическая скорость больше земной?","answer":2,"unit":"","hints":["Вырази массу планеты через её плотность и радиус."],"steps":["Для круговой орбиты у поверхности v = √(GM/R).","Масса однородной планеты M = 4πρR³/3, поэтому v = R√(4πGρ/3).","При одинаковой плотности скорость пропорциональна радиусу. Она больше в 2 раза."],"source":{"name":"Решу ЕГЭ","id":735,"type":"22","url":"https://phys-ege.sdamgia.ru/problem?id=735","note":"Краткий пересказ условия и решение Матклуба."}}];tasks.push(...bank)})();

